-- 024: the Female Representative of the Executive Committee, with photograph and biography.
-- Only fills the position while it is still empty, so later edits in the admin are never overwritten.

UPDATE leaders SET
  name = 'Counsel Alonyo Dolofine',
  photo = 'assets/img/female-representative-alonyo.webp',
  bio = 'Counsel Alonyo Dolofine serves as the Female Representative to the Gulu University Convocation, where she is committed to promoting inclusive leadership, meaningful alumni engagement, gender equality and the advancement of women within the university community and beyond. She is an Advocate, Mediator and Legal Consultant.\n\nShe holds a Bachelor of Laws (LL.B.) from Gulu University and a Diploma in Legal Practice from the Law Development Centre (LDC). She is an Advocate of the Courts of Judicature of Uganda, a Mediator and Legal Consultant practising with M/s Francis Owiny & Co. Advocates, with experience in corporate and commercial law, civil litigation, land matters, family law, succession, criminal litigation, legal advisory services and alternative dispute resolution.\n\nDolofine also serves as the Representative of Young Advocates in the Acoli Bar Forum, where she champions mentorship, professional development, equal opportunities and the empowerment of emerging legal professionals.\n\nPassionate about leadership, access to justice, education and community development, she believes in the transformative power of education and purposeful leadership.\n\nThrough her position in the Convocation, she is dedicated to strengthening alumni networks, amplifying women’s voices and fostering a vibrant, inclusive and progressive university community.'
WHERE organ = 'executive' AND title = 'Female Representative' AND (name IS NULL OR name = '');
